export type RestoredSession = { 
/**
 * Project to activate. Empty when nothing was saved or the folder is gone.
 */
project_id: string | null, 
/**
 * Document tabs that still exist on disk.
 */
tabs: Array<SessionTab>, 
/**
 * Document to focus. Empty when no saved document remains.
 */
active_rel_path: string | null, 
/**
 * Tags Cloud, Library, Graph, Dashboard and Assistant tabs to show again.
 */
workspace_tabs: Array<string>, 
/**
 * Tab to show after the documents are open.
 */
page: string, 
/**
 * View mode to apply. Empty keeps the configured default.
 */
view_mode: string, 
/**
 * User-facing notes for files and folders that could not be reopened.
 */
notices: Array<string>, };

export type UpdateCheck = { 
/**
 * Whether `latest` is newer than `current`.
 */
available: boolean, 
/**
 * Whether the latest release includes a trusted macOS zip the app can install.
 */
can_install: boolean, 
/**
 * Version of the running app, without a `v` prefix.
 */
current: string, 
/**
 * Latest GitHub Release version, without a `v` prefix.
 */
latest: string, 
/**
 * HTTPS GitHub Releases URL to open when an update is available.
 */
release_url: string, 
/**
 * HTTPS GitHub asset URL for the macOS universal zip; empty when install is not possible.
 */
asset_url: string, 
/**
 * Lowercase hex SHA-256 of that zip; empty when GitHub omitted a digest.
 */
asset_sha256: string, 
/**
 * User-facing status line; the UI displays this without further formatting.
 */
message: string, };

export type UpdateInstall = { 
/**
 * Installed GitHub Release version, without a `v` prefix.
 */
version: string, 
/**
 * User-facing status line; the UI displays this without further formatting.
 */
message: string, };
